My package already has lib/bounded_contexts/booking/api.dart (with BookingLifecycleState in lifecycles.dart) and lib/platform/event_store/event_store.dart from the main generator. The model has this lifecycle:

```hcl
lifecycle "booking" {
  aggregate = aggregate.booking.booking

  state "open" {
    path = "main"
  }
  state "confirmed" {
    end  = true
    path = "main"
  }
  state "canceled" {
    end  = true
    path = "cancel"
  }

  transition "confirm_booking" {
    command = command.confirm_booking.confirm_booking
    events  = [event.booking.booking_confirmed]
    before  = [state.open]
    after   = state.confirmed
  }
  transition "cancel_booking" {
    command = command.cancel_booking.cancel_booking
    events  = [event.booking.booking_canceled]
    before  = [state.open]
    after   = state.canceled
  }
  transition "open_booking" {
    command = command.open_booking.open_booking
    events  = [event.booking.booking_opened]
    before  = []
    after   = state.open
  }
  invalid_transition "confirm_canceled_booking" {
    command = command.confirm_booking.confirm_booking
    reason  = "A canceled booking cannot be confirmed."
    before  = [state.canceled]
  }
}
```

The aggregate booking has `identity = field_type.booking_id`. Generate the Dart code for this workflow:

```hcl
state_change "confirm_booking" {
  screen "confirm_booking_request" {
    kind         = "api"
    api_endpoint = "POST /bookings/{booking_id}/confirm"
    actor        = actor.guest
    to           = [command.confirm_booking]
  }
  command "confirm_booking" {
    aggregate = aggregate.booking.booking
    fields    = [field_type.booking.booking_id]
    to        = [event.booking.booking_confirmed]
  }
  scenario "open_booking_is_confirmed" {
    case = "happy_path"
    given { event = event.booking.booking_opened }
    when  { command = command.confirm_booking }
    then  { event = event.booking.booking_confirmed }
  }
  scenario "canceled_booking_is_not_confirmed" {
    case = "state_violation"
    given { event = event.booking.booking_opened }
    given { event = event.booking.booking_canceled }
    when  { command = command.confirm_booking }
    then  { error = "A canceled booking cannot be confirmed." }
  }
}
```
